@namespace sv_ad75ba1b8b2449ad9e0cf808b529c5f0.Components.Pages.Apply

<div class="work-entry-card">
    <div class="work-entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button class="btn-danger-sm" @onclick="() => OnRemove.InvokeAsync(Index)">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company" @onchange="e => Update(e, nameof(Entry.Company))" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title" @onchange="e => Update(e, nameof(Entry.Title))" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")" @onchange="e => Update(e, nameof(Entry.StartDate))" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@Entry.EndDate?.ToString("yyyy-MM-dd")" @onchange="e => Update(e, nameof(Entry.EndDate))" disabled="@Entry.IsCurrent" />
        </div>
        <div class="form-group form-check">
            <label>
                <input type="checkbox" checked="@Entry.IsCurrent" @onchange="e => Update(e, "IsCurrent")" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description" @onchange="e => Update(e, nameof(Entry.Description))"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<int> OnRemove { get; set; }
    [Parameter] public EventCallback<(int Index, WorkEntryModel Entry)> OnEntryChanged { get; set; }

    private void Update(ChangeEventArgs e, string field)
    {
        var updated = Entry with { };
        var value = e.Value?.ToString() ?? "";

        updated = field switch
        {
            nameof(Entry.Company) => Entry with { Company = value },
            nameof(Entry.Title) => Entry with { Title = value },
            nameof(Entry.StartDate) => Entry with { StartDate = DateTime.TryParse(value, out var d) ? d : Entry.StartDate },
            nameof(Entry.EndDate) => Entry with { EndDate = DateTime.TryParse(value, out var d2) ? d2 : null },
            "IsCurrent" => Entry with { IsCurrent = (bool)(e.Value ?? false), EndDate = (bool)(e.Value ?? false) ? null : Entry.EndDate },
            nameof(Entry.Description) => Entry with { Description = value },
            _ => Entry
        };

        OnEntryChanged.InvokeAsync((Index, updated));
    }

    public record WorkEntryModel
    {
        public string Company { get; init; } = "";
        public string Title { get; init; } = "";
        public DateTime StartDate { get; init; } = DateTime.Today;
        public DateTime? EndDate { get; init; }
        public bool IsCurrent { get; init; }
        public string Description { get; init; } = "";
    }
}

@namespace sv_ad75ba1b8b2449ad9e0cf808b529c5f0.Components.Pages.Apply

<div class="step-content">
    <h2>Work History</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message" role="alert">@ErrorMessage</div>
    }

    @for (int i = 0; i < Entries.Count; i++)
    {
        <WorkEntryForm Entry="@Entries[i]"
                       Index="@i"
                       CanRemove="@(Entries.Count > 1)"
                       OnRemove="RemoveEntry"
                       OnEntryChanged="UpdateEntry" />
    }

    <button class="btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    <div class="step-actions">
        <button class="btn-outline" @onclick="OnBack">Back</button>
        <button class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntryForm.WorkEntryModel> Entries { get; set; } = new() { new() };
    [Parameter, EditorRequired] public EventCallback<List<WorkEntryForm.WorkEntryModel>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void AddEntry()
    {
        Entries.Add(new WorkEntryForm.WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }

    private void UpdateEntry((int Index, WorkEntryForm.WorkEntryModel Entry) update)
    {
        Entries[update.Index] = update.Entry;
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;
        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                ErrorMessage = "Each position must have a company name and job title.";
                return;
            }
        }
        await OnNext.InvokeAsync(Entries);
    }
}

